using System;
class MenuGeometryTests {
 static void Assert(bool x,string m){if(!x)throw new Exception(m);}
 static int Main(){int checks=0;foreach(var size in new[]{new[]{1920f,1080f},new[]{1280f,720f},new[]{1800f,1024f},new[]{1600f,1200f}}){var g=MenuGeometry.Create(size[0],size[1]);Assert(g.Columns==6&&g.Rows==4,"24 apps on home page");checks++;for(int i=0;i<24;i++){var a=g.Slot(i);Assert(a.X-g.TileWidth/2>=g.Margin-0.1f,"left bound");Assert(a.X+g.TileWidth/2<=size[0]-g.Margin+0.1f,"right bound");Assert(-a.Y-g.TileHeight/2>=g.Top-0.1f,"header clear");Assert(-a.Y+g.TileHeight/2<=size[1]-g.Bottom+0.1f,"footer clear");checks+=4;for(int j=0;j<i;j++){var b=g.Slot(j);Assert(Math.Abs(a.X-b.X)>=g.TileWidth||Math.Abs(a.Y-b.Y)>=g.TileHeight,"hitboxes overlap");checks++;}}Assert(g.Slot(6).X==g.Slot(0).X&&g.Slot(6).Y<g.Slot(0).Y,"row order");checks++;}foreach(var size in new[]{new[]{1920f,1080f},new[]{1280f,720f},new[]{600f,400f}}){var g=MenuGeometry.Create(size[0],size[1]);Assert(16+150*g.FooterScale<=g.Bottom-8,"footer intrudes into grid");var f=g.Shape(true);Assert(f.Width==150&&f.Height==178&&f.Width<164,"folder targets overlap");var n=g.Shape(false);Assert(n.Width==g.TileWidth,"home restored after folder");for(int i=0;i<24;i++){var pt=g.Slot(i);Assert(g.HitSlot(pt.X,pt.Y)==i,"drag target differs from visual cell");Assert(g.Edge(pt.X)==0,"visible cell triggers edge paging");checks+=2;}checks+=3;}bool bad=false;try{MenuGeometry.Create(0,720);}catch(ArgumentOutOfRangeException){bad=true;}Assert(bad,"invalid size rejected");Console.WriteLine("PASS "+(++checks)+" geometry checks");return 0;}
}
